# Runs LeafID_Rizwan_Mir.ipynb top to bottom on a Kaggle GPU and keeps the executed notebook (with outputs).
import base64, os, subprocess, sys
NB_B64 = ""
os.chdir('/kaggle/working')
with open('LeafID_Rizwan_Mir.ipynb', 'wb') as f:
    f.write(base64.b64decode(NB_B64))
r = subprocess.run([sys.executable, '-m', 'jupyter', 'nbconvert', '--to', 'notebook', '--execute', '--inplace', '--allow-errors',
                    '--ExecutePreprocessor.timeout=-1', '--ExecutePreprocessor.kernel_name=python3', 'LeafID_Rizwan_Mir.ipynb'])
print('nbconvert exit code:', r.returncode)
print(sorted(os.listdir('/kaggle/working')))
